#!/usr/bin/env python3
"""Regenerate BreachEngine_Appendix_B_WireFormat.md from the plugin's type modules. Usage: gen_appendix_b.py <srcdir>"""
import re, sys
SRC = sys.argv[1]
def rd(n): return open(f"{SRC}/SerializationTools__{n}.lua", encoding="utf-8").read()
def parse_rows(body):
    rows = re.findall(r'\{\s*"([A-Za-z0-9]+)"\s*,\s*"([A-Za-z0-9]+)"\s*,\s*(.*?)\s*\}\s*,?\s*$', body, re.M)
    expect = len(re.findall(r'^\s*\{\s*"', body, re.M))
    assert len(rows) == expect, f"row parse mismatch: parsed {len(rows)} of {expect}"
    return rows
src = rd("Types__InstanceProperties"); types = rd("Types__InstanceTypes")
ids = dict((k, int(v)) for k, v in re.findall(r'\t([A-Za-z]+) = (\d+),', types))
cls = {m.group(1): parse_rows(m.group(2)) for m in re.finditer(r'^\t([A-Za-z]+) = \{\n(.*?)^\t\},', src, re.M | re.S)}
attr_cls = {'Model','Folder','Part','BoolValue','MeshPart','UnionOperation'}
CS = "bcdfghjkmpqrtvwxy346789!\"#$%&'()*+,-./:;<=>?@BCDFGHJKMPQRTVWXY[\\]^_`{|}~"
code = lambda n: CS[n]
o = ["# BreachEngine — Appendix B: Wire-Format Tables\n",
"> **Provenance: Verified (plugin source).** Generated by `tools/gen_appendix_b.py` from `Types/InstanceTypes`, `Types/InstanceProperties`, `Types/AttributeTypes`, `Types/Enums/*` and `Util/StringConversion` of SerializationTools (code version 2, API version 1). Companion to main document §4. **Revision 2:** the first edition of this appendix dropped three rows (`Part.AssemblyLinearVelocity`, `Part.AssemblyAngularVelocity`, `ParticleEmitter.Orientation`) because of a parsing bug, which also shifted every later `ParticleEmitter` id. Fixed; the generator now asserts that no row is skipped.\n",
"\n## B.1 Instance type ids\n\nOne symbol, written before every instance record. `b` (value 0) is reserved as the *end-of-children* terminator; `c` (value 1) is `Nil` (an unsupported class that was skipped).\n\n| Id | Symbol | Type | Attributes serialised? |\n|---|---|---|---|\n"]
for k, v in sorted(ids.items(), key=lambda x: x[1]):
    a = '—' if k == 'Nil' else ('yes' if k in attr_cls else ('**no** (written with no attribute section)' if k == 'PartNoAttributes' else '**no**'))
    o.append(f"| {v} | `{code(v)}` | `{k}` | {a} |\n")
o.append("\n`PartNoAttributes` is not a Roblox class: the writer substitutes it for a `Part` that has **no attributes at all**, and the reader then skips the attribute section. Only `Model`, `Folder`, `Part`, `BoolValue`, `MeshPart`, `UnionOperation` carry attributes; **attributes on every other class are silently dropped.**\n")
o.append("\n## B.2 Attribute value types\n\nOne symbol, written before each attribute (`b`/0 ends the list).\n\n| Id | Symbol | Type | Encoding | Emitted by the writer? |\n|---|---|---|---|---|\n")
enc = {'Float':'Float (5 chars)','Int':'Int (4)','String':'ShortInt index into the string map (2)','Bool':'`b`/`c` (1)','Color3':'ShortInt index into the colour map (2)','Vector3':'3 × Float (15)','LongInt':'LongInt (6)','SignedInt':'SignedInt (3)','CFrame':'CFrame (24)'}
emit = {'Float':'yes — any number that is non-integer **or negative**','LongInt':'yes — any non-negative integer','Int':'no (reader only)','SignedInt':'no (reader only)','String':'yes','Bool':'yes','Color3':'yes','Vector3':'yes','CFrame':'yes'}
for k, v in re.findall(r'\t([A-Za-z0-9]+) = (\d+),', rd("Types__AttributeTypes")):
    v = int(v); o.append(f"| {v} | `{code(v)}` | `{k}` | {enc[k]} | {emit[k]} |\n")
o.append("\nAttribute values of any other Roblox type (`UDim2`, `Vector2`, `Rect`, …) are ignored by the exporter. Attribute names beginning `RBX_` are skipped.\n")
o.append("\n## B.3 Per-class property tables\n\nA property is identified on the wire by its **1-based position in the class's list** (`Id` below), written as one symbol; the list ends with `b`. A property is written **only if its value differs from the default shown**. Value types: `String` and `Color3` are *indices into the string/colour maps* (2 chars); everything else is written inline (sizes in §4.3 of the main document).\n\n**Compatibility rule: the position is the id. Never reorder a list; only append.**\n")
for k in ids:
    if k in ('Nil', 'PartNoAttributes'): continue
    o.append(f"\n### {k}  (type id {ids[k]})\n\n| Id | Property | Value type | Default |\n|---|---|---|---|\n")
    for i, (n, t, d) in enumerate(cls[k], 1): o.append(f"| {i} | `{n}` | {t} | `{d}` |\n")
o.append("\n`PartNoAttributes` uses the exact same table as `Part`.\n")
o.append("\n### Reader-side defaults\n\nThe reader additionally forces `TopSurface = BottomSurface = SmoothNoOutlines` on every `Part` it creates (`Types/DefaultProperties`). Part properties **not** listed above (Reflectance, Locked, CanTouch, CanQuery, Massless, the other four surfaces, …) are neither written nor read.\n")
enums = {'Materials':'Types__Enums__Materials','NormalId':'Types__Enums__NormalId','PartTypes (Shape)':'Types__Enums__PartTypes','MeshType':'Types__Enums__MeshType','RenderFidelity':'Types__Enums__RenderFidelity','CollisionFidelity':'Types__Enums__CollisionFidelity','TextureMode':'Types__Enums__TextureMode','ParticleEmitterShape':'Types__Enums__Particles__ParticleEmitterShape','ParticleEmitterShapeInOut':'Types__Enums__Particles__ParticleEmitterShapeInOut','ParticleEmitterShapeStyle':'Types__Enums__Particles__ParticleEmitterShapeStyle','ParticleOrientation':'Types__Enums__Particles__ParticleOrientation','ResamplerMode':'Types__Enums__GUI__ResamplerMode','SurfaceGuiSizingMode':'Types__Enums__GUI__SurfaceGuiSizingMode'}
o.append("\n## B.4 Enum tables\n\nEnums are written as **one symbol** = the table value below (names not listed fall back to value 1 — for the 0-based tables that is the *second* entry; see Quirks, main doc §4.10).\n")
for n, f in enums.items():
    pairs = re.findall(r'([A-Za-z0-9]+) = (\d+)', rd(f))
    o.append(f"\n**{n}** — " + ", ".join(f"`{a}`={b}" for a, b in pairs) + "\n")
o.append("\n## B.5 The 72-symbol alphabet\n\nIndex → symbol, 0-based. All multi-symbol integers are big-endian base-72 over this alphabet.\n\n```\n" + CS + "\n```\n\n| Width | Max value (72^n − 1) | Used for |\n|---|---|---|\n| 1 | 71 | type ids, property ids, enums |\n| 2 | 5,183 | ShortInt, map indices, ShortBoundedFloat |\n| 3 | 373,247 | SignedInt, BoundedFloat |\n| 4 | 26,873,855 | Int (string lengths) |\n| 5 | 1,934,917,631 | — |\n| 6 | 139,314,069,503 | LongInt |\n\nCharacters `\"`, `'`, `\\`, `` ` `` and `&` appear in the alphabet. The alphabet omits lowercase `a e i l n o s u z`, digits `0 1 2 5`, and uppercase `A E I L N O S U Z` (the reason is not stated in the source; likely to avoid look-alike characters and accidental words — *inference*).\n")
open("BreachEngine_Appendix_B_WireFormat.md", "w", encoding="utf-8").write("".join(o))
print("ok")
